func TestWorkflowResumeHintSkips(t *testing.T) {
	const f = "workflow-resume-hint"
	tskip(t, f, "names a directly resumable child when the parent receipt is missing", "the hint is printed by a scripted workflow's keyed resume (`runs.run(..., {resume: {workflowRunId, key}})`) when the parent workflow receipt is missing; the port refuses workflow runs, so it has no keyed workflow resume to recover from")
	tskip(t, f, "rejects explicit baseRef when resuming a retained managed-worktree child", "the case resumes a retained managed-worktree child (handoff.json) through a scripted workflow and its baseRef check; both the workflow runtime and managed worktrees are slices the port does not run")
	tskip(t, f, "does not hint when status proof or direct resumability is not safe", "the case checks the safety conditions of the workflow keyed-resume hint (status proof, workflowChildren inventory) of a scripted workflow run; the port refuses workflow runs and keeps no workflowChildren inventory")
}
